\copy (WITH history_vehicles AS (SELECT DISTINCT vch.tenant_id, vch.vehicle_id FROM vehicle_cluster_history vch JOIN tenant_details td ON td.tenant_id = vch.tenant_id WHERE vch.week_start = '2026-11-02' AND td.tenant_drp = 2 AND (td.config->'VEHICLE_DRIVER_HISTORY'->>'enabled')::boolean IS TRUE), vehicles_with_candidate AS (SELECT DISTINCT vch.tenant_id, vch.vehicle_id FROM vehicle_cluster_history vch JOIN history_vehicles hv ON hv.tenant_id = vch.tenant_id AND hv.vehicle_id = vch.vehicle_id CROSS JOIN LATERAL jsonb_each_text(vch.cluster_counts) AS kv(key, value) JOIN cluster_details cd ON cd.cluster_id = kv.key::bigint WHERE vch.week_start = '2026-11-02' AND cd.driver_id > 0 LIMIT 200) SELECT idet.image_id, idet.tenant_id, idet.vehicle_id, idet.face_s3_path FROM image_details idet JOIN vehicles_with_candidate vwc ON vwc.vehicle_id = idet.vehicle_id AND vwc.tenant_id = idet.tenant_id WHERE idet.tenant_drp = 2 AND idet.timestamp >= '2026-11-09' AND idet.timestamp < '2026-11-16' AND NOT EXISTS (SELECT 1 FROM arcface_prediction_details apd WHERE apd.tenant_drp = 2 AND apd.timestamp >= '2026-11-09' AND apd.timestamp < '2026-11-16' AND apd.image_id = idet.image_id AND apd.predicted_driver_id > 0)) TO '/Users/swapnilmane/NetraDyne/driver_history_use/data/AN-37740/step_1/an37740_images_drp2_200vehicles.csv' WITH CSV HEADER;
